import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { investigationsList } from './generated/api'
import { InvestigationListApi } from './generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface investigationsLogicValues {
    error: string | null
    page: number
    result: InvestigationListApi | null
    resultLoading: boolean
    search: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface investigationsLogicActions {
    loadInvestigations: (_: void) => void
    loadInvestigationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadInvestigationsSuccess: (
        result: InvestigationListApi,
        payload?: void
    ) => {
        result: InvestigationListApi
        payload?: void
    }
    setPage: (page: number) => {
        page: number
    }
    setSearch: (search: string) => {
        search: string
    }
}

export type investigationsLogicType = MakeLogicType<investigationsLogicValues, investigationsLogicActions>

export const investigationsLogic = kea<investigationsLogicType>([
    path(['products', 'investigations', 'investigationsLogic']),
    actions({ setSearch: (search: string) => ({ search }), setPage: (page: number) => ({ page }) }),
    reducers({
        search: ['', { setSearch: (_, { search }) => search }],
        page: [1, { setPage: (_, { page }) => page, setSearch: () => 1 }],
        error: [
            null as string | null,
            {
                loadInvestigations: () => null,
                loadInvestigationsFailure: () => 'Could not load investigations. Try again.',
            },
        ],
    }),
    loaders(({ values }) => ({
        result: [
            null as InvestigationListApi | null,
            {
                loadInvestigations: async (_: void, breakpoint) => {
                    const result = await investigationsList(String(teamLogic.values.currentTeamId), {
                        search: values.search,
                        offset: (values.page - 1) * 30,
                        limit: 30,
                    })
                    breakpoint()
                    return result
                },
            },
        ],
    })),
    listeners(({ actions }) => ({
        setSearch: async (_, breakpoint) => {
            await breakpoint(300)
            actions.loadInvestigations()
        },
        setPage: () => actions.loadInvestigations(),
    })),
    afterMount(({ actions }) => actions.loadInvestigations()),
])
